def detailed_explanation(trait, result):
    """Structured content, available even without a DNA upload."""
    topic = DETAILS.get(trait['id'])
    if topic is None:
        raise KeyError(f"No educational explanation for {trait['id']}")
    genotype = result.get('genotype', '—')
    status = result.get('status', '')
    interpreted = status in ('Marker observed', 'Variant allele observed — unconfirmed',
                             'Two variant alleles observed — unconfirmed', 'N1303K not observed at tested site')
    if not interpreted:
        takeaway = ('Your genotype is available for research exploration, but this marker has no reviewed '
                    'genotype-specific personal prediction in Helix Explorer.' if genotype != '—' else
                    'No usable genotype was available for this marker; that does not mean the variant is absent.')
    else:
        takeaway = result.get('meaning', 'This result requires additional interpretation.')
    return {'biology': topic[0], 'importance': topic[1], 'action': topic[2],
            'takeaway': takeaway, 'interpreted': interpreted,
            'alternatives': [{'Genotype': gt, 'What it usually suggests': meaning,
                              'Your genotype': '✓ Yours' if gt == genotype else ''}
                             for gt, meaning in trait.get('alleles', {}).items()]}
